-- 0016 - Trilhos motorizados Slim: um produto por faixa (Gabriel, 28/11/2026).
-- Antes: 4 produtos (SLIMOT-0008 a 0011) com as 23 faixas escondidas no metadata.
-- Agora: 92 produtos "TRILHO MOTORIZADO - [STANDER|WAVE] - ATÉ [metros] MT - [BRANCO|PRETO]",
-- de 1,00 a 12,00 m (passo 0,50 m). Custo = tabela do fabricante (sem margem).
-- Venda = custo x a mesma proporção venda/custo que o produto da 1ª faixa tem hoje (markup 100% = x2).
-- Os 4 SKUs atuais viram a faixa ATÉ 1,00 MT; SLIMOT-0012 a 0099 são as outras faixas.
-- metadata.faixas_skus (em todos da família) diz ao cálculo qual produto usar pela largura:
-- 4,35 m usa o ATÉ 4,50; 4,00 m usa o ATÉ 4,00. Acima de 12 m a fábrica não produz.

CREATE TEMP TABLE trilhos_0016 (sku TEXT, nome TEXT, cor TEXT, custo NUMERIC, meta JSONB, base TEXT, primeira BOOLEAN) ON COMMIT DROP;

-- Proporção venda/custo de cada família (do produto da 1ª faixa como está hoje; sem ele, x2).
CREATE TEMP TABLE fator_0016 ON COMMIT DROP AS
SELECT t.base, COALESCE((SELECT CASE WHEN p.custo_unitario > 0 THEN p.preco_venda_unitario / p.custo_unitario END FROM produtos p WHERE p.sku = t.base), 2) AS fator
FROM (SELECT DISTINCT base FROM trilhos_0016) t;

-- 1ª faixa: os 4 produtos que já existem (mantém id, histórico e status).
UPDATE produtos p SET nome = t.nome, cor_colecao = t.cor, custo_unitario = t.custo,
  preco_venda_unitario = ROUND(t.custo * f.fator, 2),
  metadata_tecnica = (p.metadata_tecnica - 'faixas') || t.meta, atualizado_em = NOW()
FROM trilhos_0016 t JOIN fator_0016 f ON f.base = t.base
WHERE t.primeira AND p.sku = t.sku;

-- Demais faixas: produtos novos, na mesma categoria e fornecedor da 1ª faixa.
SELECT t.sku, COALESCE(b.categoria_id, 33), b.fornecedor_padrao_id, t.nome, t.cor, 'PC', t.custo, ROUND(t.custo * f.fator, 2), t.meta, COALESCE(b.ativo, TRUE)
FROM trilhos_0016 t
JOIN fator_0016 f ON f.base = t.base
LEFT JOIN produtos b ON b.sku = t.base
WHERE NOT t.primeira
ON CONFLICT (sku) DO NOTHING;
